import { createHash, createPublicKey, randomBytes, verify } from "node:crypto";
import {
  accessSync,
  chmodSync,
  constants,
  mkdirSync,
  readFileSync,
  renameSync,
  statSync,
  unlinkSync,
} from "node:fs";
import { open } from "node:fs/promises";
import { homedir } from "node:os";
import { delimiter, extname, isAbsolute, join } from "node:path";

import {
  BINARY_RELEASE,
  BINARY_RELEASE_BASE_DEFAULT,
  BINARY_SIGNING_PUBKEY,
} from "./release.generated.mjs";

function executable(path) {
  try {
    if (process.platform !== "win32") accessSync(path, constants.X_OK);
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

export function executableCandidateNames(
  name,
  platform = process.platform,
  pathExt = process.env.PATHEXT ?? ".COM;.EXE;.BAT;.CMD",
) {
  if (platform !== "win32" || extname(name)) return [name];
  const candidates = [];
  for (const extension of pathExt.split(";").map((value) => value.trim()).filter(Boolean)) {
    candidates.push(`${name}${extension.startsWith(".") ? extension : `.${extension}`}`);
  }
  // npm installs a POSIX shim beside its native .CMD shim. Windows X_OK is
  // existence-only, so native PATHEXT candidates must win before bare fallback.
  candidates.push(name);
  const seen = new Set();
  return candidates.filter((candidate) => {
    const key = candidate.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function onPath(name) {
  if (isAbsolute(name) || /[\\/]/.test(name)) return executable(name) ? name : null;
  for (const dir of (process.env.PATH ?? "").split(delimiter)) {
    if (!dir) continue;
    for (const candidate of executableCandidateNames(name)) {
      const path = join(dir, candidate);
      if (executable(path)) return path;
    }
  }
  return null;
}

export function targetPlatform(os = process.platform, nodeArch = process.arch) {
  const arch = nodeArch === "x64" ? "amd64" : nodeArch;
  if (!(os === "darwin" || os === "linux" || os === "win32") ||
      !(arch === "arm64" || arch === "amd64")) {
    throw new Error(`no prebuilt binary for ${os}/${arch} — supported: darwin/arm64, darwin/amd64, linux/arm64, linux/amd64, win32/arm64, win32/amd64`);
  }
  return { os, arch };
}

export function binaryInstallFilename(name, os = process.platform) {
  return os === "win32" ? `${name}.exe` : name;
}

function timeoutMs() {
  const raw = process.env.CAVE_SETUP_TIMEOUT ?? "300";
  const seconds = Number(raw);
  if (!Number.isInteger(seconds) || seconds <= 0) {
    throw new Error(`CAVE_SETUP_TIMEOUT must be a positive integer (got ${JSON.stringify(raw)})`);
  }
  return seconds * 1000;
}

async function asset(url, timeout) {
  let response;
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(timeout) });
  } catch (error) {
    throw new Error(`binary download failed: ${error.message}`);
  }
  if (!response.ok) throw new Error(`binary download failed: HTTP ${response.status}`);
  return response;
}

function signedDigest(checksums, bundleRaw) {
  try {
    const bundle = JSON.parse(bundleRaw);
    if (bundle.mediaType !== "application/vnd.dev.sigstore.bundle.v0.3+json") return false;
    if (bundle.messageSignature?.messageDigest?.algorithm !== "SHA2_256") return false;
    const digest = createHash("sha256").update(checksums).digest();
    const bundled = Buffer.from(bundle.messageSignature.messageDigest.digest, "base64");
    if (digest.length !== bundled.length || !digest.equals(bundled)) return false;
    return verify(
      "sha256",
      Buffer.from(checksums),
      createPublicKey(BINARY_SIGNING_PUBKEY),
      Buffer.from(bundle.messageSignature.signature, "base64"),
    );
  } catch {
    return false;
  }
}

function expectedDigest(checksums, artifact) {
  for (const line of checksums.split("\n")) {
    if (!line) continue;
    const match = line.match(/^([a-f0-9]{64})  ([A-Za-z0-9._-]+)$/);
    if (!match) throw new Error("signed checksum manifest is malformed");
    if (match[2] === artifact) return match[1];
  }
  throw new Error(`signed checksum manifest does not contain ${artifact}`);
}

function cleanup(path) {
  try {
    unlinkSync(path);
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
}

async function download(url, part, timeout) {
  const response = await asset(url, timeout);
  if (!response.body) throw new Error("binary download failed: response body missing");
  const hash = createHash("sha256");
  const file = await open(part, constants.O_CREAT | constants.O_EXCL | constants.O_WRONLY, 0o600);
  const reader = response.body.getReader();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      hash.update(value);
      await file.write(value);
    }
  } finally {
    reader.releaseLock();
    await file.close();
  }
  return hash.digest("hex");
}

// Windows refuses to replace a file another process holds open, and the
// binaries this installs (caveman-proxy, cavemem) are long-lived daemons — an
// update issued while one is running failed the rename outright and then the
// catch deleted the verified download, so the user was left with neither the
// new binary nor a retry (#657). Back off and try again; the daemon usually
// exits within a second or two of being asked to.
async function replaceWithRetry(part, target, attempts = 6) {
  for (let attempt = 0; ; attempt++) {
    try {
      renameSync(part, target);
      return;
    } catch (error) {
      const locked = error.code === "EPERM" || error.code === "EBUSY" ||
                     error.code === "EACCES" || error.code === "ETXTBSY";
      if (!locked || attempt >= attempts - 1) throw error;
      await new Promise((done) => setTimeout(done, 100 * 2 ** attempt));
    }
  }
}

export async function ensureBinary({ name, envVar }) {
  const explicit = process.env[envVar];
  if (explicit) {
    if (!executable(explicit)) throw new Error(`${envVar} does not point to an executable: ${explicit}`);
    return explicit;
  }
  const found = onPath(name);
  if (found) return found;
  const binDir = join(process.env.CAVEMAN_HOME ?? join(homedir(), ".caveman"), "bin");
  const target = join(binDir, binaryInstallFilename(name));
  if (executable(target)) return target;

  const { os, arch } = targetPlatform();
  const artifact = `${name}_${os}_${arch}`;
  const base = (process.env.CAVE_BINARY_RELEASE_BASE ?? BINARY_RELEASE_BASE_DEFAULT).replace(/\/+$/, "");
  const release = `${base}/${BINARY_RELEASE}`;
  const timeout = timeoutMs();
  const [checksumsResponse, signatureResponse] = await Promise.all([
    asset(`${release}/checksums.txt`, timeout),
    asset(`${release}/checksums.txt.keysig`, timeout),
  ]);
  const [checksums, signature] = await Promise.all([checksumsResponse.text(), signatureResponse.text()]);
  if (!signedDigest(checksums, signature)) {
    throw new Error("signature check failed for checksums.txt — refusing to install");
  }
  const expected = expectedDigest(checksums, artifact);
  mkdirSync(binDir, { recursive: true });
  // Per-process part path, and NO pre-unlink. A fixed `${target}.part` plus a
  // cleanup() immediately before an O_CREAT|O_EXCL open made the exclusivity
  // guard unreachable: two concurrent installs (npx -y caveman-mcp is registered
  // per MCP session, so several agents can start one at once) raced — B unlinked
  // A's directory entry and created its own inode, A hashed ITS OWN bytes and
  // matched, and then the PATH-based chmod+rename published B's half-written file
  // as "checksum verified". Both the chmod and the rename now act on a name only
  // this process can own.
  //
  // ponytail: a SIGKILL mid-download now leaves one stray .part behind instead of
  // reusing the fixed name. Sweep binDir for stale .part files if that ever shows
  // up in the wild.
  const part = `${target}.${process.pid}.${randomBytes(6).toString("hex")}.part`;
  try {
    const actual = await download(`${release}/${artifact}`, part, timeout);
    if (actual !== expected) throw new Error(`signature check failed for ${artifact} — partial download deleted`);
    chmodSync(part, 0o755);
    await replaceWithRetry(part, target);
  } catch (error) {
    cleanup(part);
    throw error;
  }
  process.stderr.write(`${name}  ${os}/${arch}  checksum verified\n`);
  return target;
}

#!/usr/bin/env node
// Launcher for caveman-shrink. The tool itself is the prebuilt Go
// `caveman-shrink` binary (it links the engine's tool-schema compressor); this
// shim locates and execs it, forwarding args and stdio.
//
import { spawn } from "node:child_process";
import { ensureBinary } from "./binary-installer.generated.mjs";

let bin;
try {
  bin = await ensureBinary({ name: "caveman-shrink", envVar: "CAVEMAN_SHRINK_BIN" });
} catch (error) {
  process.stderr.write(`caveman-shrink: ${error.message}\n`);
  process.exit(127);
}
const child = spawn(bin, process.argv.slice(2), { stdio: "inherit" });

child.on("error", (err) => {
  if (err.code === "ENOENT") {
    process.stderr.write(`caveman-shrink: verified binary disappeared before launch (${bin})\n`);
    process.exit(127);
  }
  process.stderr.write(`caveman-shrink: ${err.message}\n`);
  process.exit(1);
});

child.on("exit", (code, signal) => {
  if (signal) process.kill(process.pid, signal);
  else process.exit(code ?? 0);
});

// Generated by packages/cli/scripts/gen-wedge-installer.mjs. Do not edit.
export const BINARY_RELEASE = "bin-v1.1.3";
export const BINARY_RELEASE_BASE_DEFAULT = "https://github.com/JuliusBrussee/caveman/releases/download";
export const BINARY_SIGNING_PUBKEY = "-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEKR5zq0dz0mTUtkiX0b6jqtyG3uQV\n89PGD2n9UBV1ikbhu0f1c+vHtcN9mk6wKzyBLdEPudI/Jnvci+8OAen/vw==\n-----END PUBLIC KEY-----\n";

// Command caveman-shrink compresses MCP/OpenAI tool catalogs.
//
//	caveman-shrink               compress stdin → stdout; JSON report on stderr
//	caveman-shrink shrink        same as above (explicit)
//	caveman-shrink lint FILE     print per-tool inferred token reductions
//	caveman-shrink recover HAND  print the original catalog for a recovery handle
//
// Everything it reports is `inferred`. The S4 compress path is fail-open: on any
// problem it forwards the original bytes unchanged. A shrink writes the original to
// the durable recovery store (CAVEMAN_CCR_DB / ~/.caveman/ccr.db), so a handle it
// prints resolves later via `recover`.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/JuliusBrussee/caveman/shrink"
)

const maxStdinBytes int64 = 32 << 20

func main() {
	args := os.Args[1:]
	cmd := "shrink"
	if len(args) > 0 {
		cmd = args[0]
	}
	switch cmd {
	case "shrink":
		runShrink()
	case "lint":
		runLint(args[1:])
	case "recover":
		runRecover(args[1:])
	case "help", "--help", "-h":
		fmt.Fprintln(os.Stderr, "caveman-shrink [shrink] | lint <file> | recover <handle>")
	default:
		// No subcommand: treat the whole invocation as a shrink over stdin.
		runShrink()
	}
}

func runShrink() {
	input, err := readBoundedInput(os.Stdin, maxStdinBytes)
	if err != nil {
		fatal("read stdin: %v", err)
	}
	res, err := shrink.Shrink(input)
	if err != nil {
		// Byte-safe: forward the original unchanged rather than fail.
		_, _ = os.Stdout.Write(input)
		fmt.Fprintf(os.Stderr, `{"ratio":0,"basis":"inferred","note":"passed through: %v"}`+"\n", err)
		return
	}
	if _, err := os.Stdout.Write(res.Output); err != nil {
		fatal("write stdout: %v", err)
	}
	report, _ := json.Marshal(res)
	fmt.Fprintln(os.Stderr, string(report))
}

func readBoundedInput(r io.Reader, maxBytes int64) ([]byte, error) {
	input, err := io.ReadAll(io.LimitReader(r, maxBytes+1))
	if err != nil {
		return nil, err
	}
	if int64(len(input)) > maxBytes {
		return nil, fmt.Errorf("cave_input_too_large: stdin exceeds %d bytes", maxBytes)
	}
	return input, nil
}

func runLint(args []string) {
	if len(args) < 1 {
		fatal("usage: caveman-shrink lint <file>")
	}
	input, err := os.ReadFile(args[0])
	if err != nil {
		fatal("read %s: %v", args[0], err)
	}
	rep, err := shrink.Lint(input)
	if err != nil {
		fatal("lint: %v", err)
	}
	fmt.Printf("%-28s %10s %10s %8s\n", "TOOL", "BEFORE", "AFTER", "RATIO")
	for _, t := range rep.Tools {
		fmt.Printf("%-28s %10d %10d %7.1f%%\n", t.Name, t.TokensBefore, t.TokensAfter, t.Ratio*100)
	}
	fmt.Printf("%-28s %10d %10d %7.1f%%  (basis: %s)\n", "TOTAL", rep.TokensBefore, rep.TokensAfter, rep.Ratio*100, rep.Basis)
}

func runRecover(args []string) {
	if len(args) < 1 {
		fatal("usage: caveman-shrink recover <handle>")
	}
	original, err := shrink.Recover(args[0])
	if err != nil {
		fatal("recover %s: %v", args[0], err)
	}
	if _, err := os.Stdout.Write(original); err != nil {
		fatal("write stdout: %v", err)
	}
}

func fatal(format string, args ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}

package main

import (
	"bytes"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

const cliRoundTripCatalog = `{"tools":[{"name":"search","description":"Search files in the workspace. This intentionally long filler sentence describes ranking, traversal, context windows, result formatting, pagination, workspace roots, ignore files, symlinks, hidden files, binary detection, and many other details that do not affect tool selection.","inputSchema":{"type":"object","title":"A deliberately verbose annotation title that is removable without changing selection or argument construction","$comment":"A deliberately verbose schema comment containing implementation notes, examples, historical context, and other annotation-only prose that the compressor may remove safely.","properties":{"query":{"type":"string","description":"Query text.","examples":["first long example query","second long example query","third long example query","fourth long example query"]}},"required":["query"]}}]}`

func TestShrinkAndRecoverAcrossProcesses(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "ccr.db")
	shrinkCmd := helperCommand(t, dbPath, "shrink")
	shrinkCmd.Stdin = bytes.NewBufferString(cliRoundTripCatalog)
	var shrunk, report bytes.Buffer
	shrinkCmd.Stdout = &shrunk
	shrinkCmd.Stderr = &report
	if err := shrinkCmd.Run(); err != nil {
		t.Fatalf("shrink subprocess: %v\nstderr=%s", err, report.String())
	}
	if bytes.Equal(shrunk.Bytes(), []byte(cliRoundTripCatalog)) {
		t.Fatal("fixture did not compress")
	}
	var result struct {
		RecoveryHandle string `json:"recovery_handle"`
	}
	if err := json.Unmarshal(bytes.TrimSpace(report.Bytes()), &result); err != nil {
		t.Fatalf("decode shrink report: %v\nreport=%s", err, report.String())
	}
	if result.RecoveryHandle == "" {
		t.Fatal("compressing CLI run did not print a recovery handle")
	}

	recoverCmd := helperCommand(t, dbPath, "recover", result.RecoveryHandle)
	var recovered, recoverErr bytes.Buffer
	recoverCmd.Stdout = &recovered
	recoverCmd.Stderr = &recoverErr
	if err := recoverCmd.Run(); err != nil {
		t.Fatalf("recover subprocess: %v\nstderr=%s", err, recoverErr.String())
	}
	if !bytes.Equal(recovered.Bytes(), []byte(cliRoundTripCatalog)) {
		t.Fatalf("recovered bytes differ:\n got=%s\nwant=%s", recovered.Bytes(), cliRoundTripCatalog)
	}
}

func TestReadBoundedInput(t *testing.T) {
	got, err := readBoundedInput(strings.NewReader("1234"), 4)
	if err != nil || string(got) != "1234" {
		t.Fatalf("input at limit: got=%q err=%v", got, err)
	}
	if _, err := readBoundedInput(strings.NewReader("12345"), 4); err == nil || !strings.Contains(err.Error(), "cave_input_too_large") {
		t.Fatalf("oversized input error = %v", err)
	}
}

func helperCommand(t *testing.T, dbPath string, args ...string) *exec.Cmd {
	t.Helper()
	commandArgs := append([]string{"-test.run=TestShrinkCLIHelperProcess", "--"}, args...)
	cmd := exec.Command(os.Args[0], commandArgs...)
	environment := make([]string, 0, len(os.Environ())+2)
	for _, entry := range os.Environ() {
		if strings.HasPrefix(entry, "CAVEMAN_SHRINK_HELPER=") || strings.HasPrefix(entry, "CAVEMAN_CCR_DB=") {
			continue
		}
		environment = append(environment, entry)
	}
	cmd.Env = append(environment, "CAVEMAN_SHRINK_HELPER=1", "CAVEMAN_CCR_DB="+dbPath)
	return cmd
}

func TestShrinkCLIHelperProcess(t *testing.T) {
	if os.Getenv("CAVEMAN_SHRINK_HELPER") != "1" {
		return
	}
	separator := 0
	for index, arg := range os.Args {
		if arg == "--" {
			separator = index + 1
			break
		}
	}
	if separator == 0 {
		os.Exit(2)
	}
	os.Args = append([]string{"caveman-shrink"}, os.Args[separator:]...)
	main()
	os.Exit(0)
}

